 "content": "def transform(grid):
    """Restore the central 2-mask from the grid's bilateral mirror symmetry."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                orbit = {(r, c), (h - 1 - r, c), (r, w - 1 - c), (h - 1 - r, w - 1 - c)}
                known = [grid[rr][cc] for rr, cc in orbit if grid[rr][cc] != 2]
                if known:
                    # All visible orbit cells agree in the demonstrated symmetric patterns.
                    out[r][c] = known[0]
    return out

